mapper.update:
UPDATE collect_flow
SET collect_flow_record_count = COALESCE(collect_flow_record_count, 0) + #{delta}
WHERE collect_flow_id = #{flowId}

UPDATE collect_flow
SET collect_flow_running = collect_flow_running + 1
WHERE collect_flow_id = #{flowId}
  AND collect_flow_is_deleted = 0
  AND collect_flow_running < #{limit}

mapper.select:
SELECT COALESCE(collect_flow_running, 0)
FROM collect_flow
WHERE collect_flow_id = #{flowId}
